<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Contrast Ratio Checker','description'=>'Calculate the contrast ratio between two colors.','url'=>'https://smarttoolz.in/tools/color-contrast-ratio/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Color Contrast Ratio</h1><p>Check contrast between foreground and background colors.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Foreground<input id="a" type="color" value="#000000"></label><label>Background<input id="b" type="color" value="#ffffff"></label><p id="o"></p></div></section></main><script>function lum(h){let a=[0,2,4].map(i=>parseInt(h.slice(1+i,3+i),16)/255).map(x=>x<=.03928?x/12.92:Math.pow((x+.055)/1.055,2.4));return .2126*a[0]+.7152*a[1]+.0722*a[2]}function go(){let x=lum(a.value),y=lum(b.value);o.textContent=`Contrast ratio: ${(Math.max(x,y)+.05)/(Math.min(x,y)+.05).toFixed(2)}:1`}a.oninput=b.oninput=go;go()</script><?php smarttoolz_tool_page_end(); ?>